from dataclasses import dataclass, field, asdict, replace

@dataclass(frozen=True, order=True)
class Item:
    name: str
    price: int
    tags: tuple = ()

a, b = Item("а", 5), Item("б", 3)
print(sorted([a, b])[0].name, asdict(a))
print(replace(a, price=10))
try:
    a.price = 1
except Exception as e:
    print(type(e).__name__)

@dataclass
class Cart:
    items: list = field(default_factory=list)
    def __post_init__(self):
        self.count = len(self.items)

print(Cart([1, 2]).count, Cart().items)

from typing import Callable, Literal, Any

def apply(f: Callable[[int], int], x: int) -> int:
    return f(x)

Mode = Literal["r", "w"]

def open_mode(m: Mode) -> str:
    return f"режим {m}"

def parse(v: Any) -> int:
    return int(v)

print(apply(abs, -5), open_mode("r"), parse("7"))

from typing import TypedDict, NamedTuple, Protocol

class Movie(TypedDict):
    title: str
    year: int

class Point(NamedTuple):
    x: int
    y: int

class Speaker(Protocol):
    def speak(self) -> str: ...

class Dog:
    def speak(self) -> str:
        return "гав"

def talk(s: Speaker) -> str:
    return s.speak()

m: Movie = {"title": "Матрица", "year": 1999}
print(m["year"], Point(1, 2), talk(Dog()))

from dataclasses import dataclass, field

try:
    @dataclass
    class Bad:
        items: list = []
except ValueError as e:
    print(e)

@dataclass
class Good:
    items: list = field(default_factory=list)

print(Good().items is Good().items)
